@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    @* Stats Bar *@
    <div class="board-stats">
        <span>Total: @allTasks.Count</span>
        <span>To Do: @todoTasks.Count</span>
        <span>In Progress: @inProgressTasks.Count</span>
        <span>Done: @doneTasks.Count</span>
        <span class="overdue-count">Overdue: @overdueTasks.Count</span>
    </div>

    @* Search Bar *@
    <div class="board-search">
        <input type="text" placeholder="Search tasks by title…" @bind="searchText" @bind:event="oninput" />
    </div>

    @* Kanban Columns *@
    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      ColumnStatus="To Do"
                      Tasks="filteredTodo"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="MoveToInProgress"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="In Progress"
                      ColumnStatus="In Progress"
                      Tasks="filteredInProgress"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="MoveToToDo"
                      OnMoveRight="MoveToDone"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="Done"
                      ColumnStatus="Done"
                      Tasks="filteredDone"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="MoveToInProgress_FromDone"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> filteredTodo => Filter(todoTasks);
    private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
    private List<TaskItem> filteredDone => Filter(doneTasks);

    private List<TaskItem> Filter(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }

    private async Task MoveToInProgress(TaskItem task)
    {
        await MoveTask(task, "In Progress");
    }

    private async Task MoveToToDo(TaskItem task)
    {
        await MoveTask(task, "To Do");
    }

    private async Task MoveToDone(TaskItem task)
    {
        await MoveTask(task, "Done");
    }

    private async Task MoveToInProgress_FromDone(TaskItem task)
    {
        await MoveTask(task, "In Progress");
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
        var index = allTasks.FindIndex(t => t.Id == task.Id);
        if (index >= 0)
        {
            allTasks[index] = task with { Status = newStatus };
        }
    }
}

