.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.board-stats span {
    font-weight: 600;
}

.overdue-count {
    color: #dc3545;
}

.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.95rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

::deep .kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-width: 250px;
}

::deep .column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .column-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .task-count {
    background: #dee2e6;
    border-radius: 12px;
    padding: 0.15rem 0.6rem;
    font-size: 0.8rem;
    font-weight: 600;
}

::deep .task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .task-assignee {
    margin: 0 0 0.4rem;
    font-size: 0.85rem;
    color: #6c757d;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background: #28a745;
    color: #fff;
}

::deep .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #e9ecef;
}

::deep .btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
    font-size: 0.9rem;
}

::deep .btn-add-task:hover {
    background: #e9ecef;
}

::deep .add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

::deep .add-task-form input,
::deep .add-task-form select {
    padding: 0.4rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-save:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading {
    text-align: center;
    padding: 2rem;
    color: #6c757d;
}

.error-message {
    padding: 1rem;
    background: #f8d7da;
    border: 1px solid #f5c6cb;
    border-radius: 6px;
    color: #721c24;
}

.error-message button {
    margin-top: 0.5rem;
    padding: 0.4rem 0.75rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

